{
  "title": "The Rescue of Ashenford",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A rescue party gathers at the edge of the ruined city.",
      "visual_description": "Four travelers crest a windswept hill at dusk, looking down on a shattered royal city with broken spires and smoking rooftops; tattered banners flap in the foreground.",
      "characters": ["Captain Rowan", "Mira the Mapwright", "Sable the Scout", "Old Hob"]
    },
    {
      "scene_number": 2,
      "caption": "Mira unrolls a map of the fallen capital.",
      "visual_description": "By a small campfire, Mira spreads a glowing vellum map across a flat stone, fingers tracing routes; the others lean in, faces lit orange.",
      "characters": ["Mira the Mapwright", "Captain Rowan", "Sable the Scout", "Old Hob"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the cracked castle gates at dawn.",
      "visual_description": "Massive iron-bound gates hang askew between two crumbling towers; pale dawn light spills through the breach, illuminating the small party as silhouettes.",
      "characters": ["Captain Rowan", "Sable the Scout", "Mira the Mapwright", "Old Hob"]
    },
    {
      "scene_number": 4,
      "caption": "Sable slips ahead to scout the inner courtyard.",
      "visual_description": "A lithe figure in gray hood vaults a broken statue, crouching low among shattered cobblestones and overturned market stalls.",
      "characters": ["Sable the Scout"]
    },
    {
      "scene_number": 5,
      "caption": "Frightened townspeople whisper warnings from a cellar.",
      "visual_description": "Two gaunt civilians peer up from a cellar hatch in a ruined bakery, clutching a child; Sable kneels at the opening, finger to her lips.",
      "characters": ["Sable the Scout", "Bram the Baker", "Lila the Child"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon coil over the rooftops.",
      "visual_description": "From a high broken window, the party watches distant smoke spiral above the cursed tower; a serpentine shadow flickers behind the haze, just suggestion.",
      "characters": ["Captain Rowan", "Mira the Mapwright", "Old Hob"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches through the plaza below.",
      "visual_description": "Six black-armored soldiers in iron helms trudge past a fountain choked with weeds; the party flattens against a balustrade overhead, holding breath.",
      "characters": ["Captain Rowan", "Sable the Scout", "Mira the Mapwright", "Old Hob", "Iron Captain Vael"]
    },
    {
      "scene_number": 8,
      "caption": "Old Hob almost gives them away with a sneeze.",
      "visual_description": "Hob's nose scrunches comically as dust drifts down; Rowan clamps a gauntleted hand over Hob's face, eyes wide; Sable glares.",
      "characters": ["Old Hob", "Captain Rowan", "Sable the Scout"]
    },
    {
      "scene_number": 9,
      "caption": "They reach a sealed door etched with glowing runes.",
      "visual_description": "A tall arched door of black stone pulses with pale blue sigils; Mira raises a hand, runes reflecting in her eyes, while the others wait tensely.",
      "characters": ["Mira the Mapwright", "Captain Rowan", "Sable the Scout", "Old Hob"]
    },
    {
      "scene_number": 10,
      "caption": "Mira coaxes the magic door open with a whispered key.",
      "visual_description": "Tendrils of silver light unspool from Mira's lips into the door's central rune; the sigils flare and the slab grinds aside, revealing a dark stair.",
      "characters": ["Mira the Mapwright", "Captain Rowan", "Sable the Scout", "Old Hob"]
    },
    {
      "scene_number": 11,
      "caption": "They descend beneath the cursed tower.",
      "visual_description": "A spiral stair winds down between dripping walls; lantern light flickers on chained banners of an old royal house pinned to the stone.",
      "characters": ["Captain Rowan", "Sable the Scout", "Mira the Mapwright", "Old Hob"]
    },
    {
      "scene_number": 12,
      "caption": "They find the captive prince in a glass cell.",
      "visual_description": "Inside a circular chamber, a pale young man in tattered finery sits inside a tall cylinder of greenish crystal; sigils crawl across its surface.",
      "characters": ["Prince Aldren", "Captain Rowan", "Mira the Mapwright", "Sable the Scout", "Old Hob"]
    },
    {
      "scene_number": 13,
      "caption": "Mira shatters the binding while Sable watches the stair.",
      "visual_description": "Mira slams a glowing palm to the crystal; cracks spiderweb outward in white light. Sable crouches at the doorway, bow drawn toward the stairwell.",
      "characters": ["Mira the Mapwright", "Prince Aldren", "Sable the Scout", "Captain Rowan"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm bells ring as the patrol storms the tower.",
      "visual_description": "Bronze bells swing wildly in a cracked belfry above; armored figures pour up the spiral stair with torches and spears, Vael at their head.",
      "characters": ["Iron Captain Vael"]
    },
    {
      "scene_number": 15,
      "caption": "The party flees through the burning market.",
      "visual_description": "Stalls blaze on either side as the five sprint down a narrow lane; Rowan covers the rear with a raised shield, sparks raining around them.",
      "characters": ["Captain Rowan", "Mira the Mapwright", "Sable the Scout", "Old Hob", "Prince Aldren"]
    },
    {
      "scene_number": 16,
      "caption": "A true dragon rises over the cursed tower behind them.",
      "visual_description": "A vast red dragon uncoils from the tower's broken crown, wings spread against a smoke-orange sky; the runners are tiny silhouettes in the foreground.",
      "characters": ["Captain Rowan", "Mira the Mapwright", "Sable the Scout", "Old Hob", "Prince Aldren", "The Ember Wyrm"]
    },
    {
      "scene_number": 17,
      "caption": "Old Hob leaps the broken span of the river bridge.",
      "visual_description": "On a half-collapsed stone bridge, Hob soars mid-jump across a yawning gap, robes flapping; the prince stares in disbelief as the others wait on the far side.",
      "characters": ["Old Hob", "Prince Aldren", "Captain Rowan", "Mira the Mapwright", "Sable the Scout"]
    },
    {
      "scene_number": 18,
      "caption": "They cross to safety as the city burns behind them.",
      "visual_description": "The party walks away across a green meadow at sunrise; behind them, the ruined city smolders under the circling dragon, banners curling to ash.",
      "characters": ["Captain Rowan", "Mira the Mapwright", "Sable the Scout", "Old Hob", "Prince Aldren"]
    }
  ]
}

